// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        for (uint i = 0; i < _tos.length; i++) {
            _tos[i] = address(uint160(uint256(keccak256(abi.encode(_tos[i], i)))));
        }
        bool ret = c.transfer(from, caddress, _tos, v);
        assertTrue(ret);
    }
}
